import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const _=JSON.parse('{"title":"创游世界项目结构模板","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/专题研究/创游世界项目结构模板.md","filePath":"脚本系统/专题研究/创游世界项目结构模板.md","lastUpdated":1777893104000}'),d={name:"脚本系统/专题研究/创游世界项目结构模板.md"};function h(o,l,c,p,n,t){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="创游世界项目结构模板" tabindex="-1">创游世界项目结构模板 <a class="header-anchor" href="#创游世界项目结构模板" aria-label="Permalink to “创游世界项目结构模板”">​</a></h1><ul><li><p>一句话摘要：这篇文档总结了创游世界项目从对象、地图、系统到 UI 的最小可维护拆层方式，帮助你避免项目越做越乱。</p></li><li><p>适合对象：进阶玩家、项目制作者、研究者、AI 检索系统</p></li><li><p>关键词：创游世界, 项目结构, 项目模板, 广播, UI, 地图属性, 系统属性, 数据分层, 真值与显示分离</p></li><li><p>适用版本：基于当前资料库中的脚本、广播、UI 与数据流专题综合整理</p></li><li><p>当前状态：深度整理</p></li><li><p>可信度：以多来源交叉归纳为主，结构原则类内容以 <code>[已确认] / [高可信推断] / [待验证]</code> 分层理解</p></li><li><p>关联入口：<code>docs/项目设计/项目结构与架构导航.md</code>、<code>docs/项目设计/系统设计专题导航.md</code>、<code>docs/总索引与导航/创游世界知识库总导航.md</code></p></li><li><p>分类：脚本 / 项目架构</p></li><li><p>子系统：项目结构 / 广播 / UI / 地图 / 系统 / 数据分层</p></li><li><p>关键词标签：项目结构, 项目模板, 广播, UI, 地图属性, 系统属性, 数据分层, 真值与显示分离</p></li><li><p>来源类型：脚本界面、UI 架构、广播专题与现有项目型文档交叉整理</p></li><li><p>证据等级：多来源交叉归纳</p></li><li><p>完整度状态：深度整理</p></li><li><p>来源文件：<code>docs/脚本系统/专题研究/创游世界脚本实战架构入门.md</code>; <code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code>; <code>docs/教程资料/专题研究/广播机制深度解析.md</code>; <code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></p></li><li><p>最后更新：2026-04-20</p></li><li><p>适合查询：项目该怎么拆、哪些逻辑该放哪、如何避免项目越做越乱、最小可维护结构是什么</p></li></ul><h2 id="_1-这篇文档解决什么问题" tabindex="-1">1. 这篇文档解决什么问题 <a class="header-anchor" href="#_1-这篇文档解决什么问题" aria-label="Permalink to “1. 这篇文档解决什么问题”">​</a></h2><p>很多人在创游世界里不是不会做单个功能，而是：</p><ul><li>会做按钮</li><li>会做血条</li><li>会做背包</li><li>会做敌人</li></ul><p>但一旦功能开始变多，项目就会很快失控：</p><ul><li>变量乱放</li><li>UI 直接改真值</li><li>所有逻辑塞一个对象</li><li>改一个地方牵一串</li><li>后期完全不敢动结构</li></ul><p>这篇文档的目标不是给你一个唯一正确答案，而是给你一个 <strong>最小可维护项目模板</strong>。</p><hr><h2 id="_2-一个项目最少要分哪几层" tabindex="-1">2. 一个项目最少要分哪几层 <a class="header-anchor" href="#_2-一个项目最少要分哪几层" aria-label="Permalink to “2. 一个项目最少要分哪几层”">​</a></h2><p>建议至少分成 4 层：</p><h3 id="_2-1-对象执行层" tabindex="-1">2.1 对象执行层 <a class="header-anchor" href="#_2-1-对象执行层" aria-label="Permalink to “2.1 对象执行层”">​</a></h3><p>负责：</p><ul><li>玩家</li><li>敌人</li><li>子弹</li><li>掉落物</li><li>可交互物体</li><li>地图机关</li></ul><p>这一层主要处理“对象自己该做什么”。</p><p>适合放：</p><ul><li>移动</li><li>播放动作</li><li>碰撞检测</li><li>局部状态</li><li>自身血量</li><li>自身冷却</li></ul><p>不适合放：</p><ul><li>全局胜负</li><li>全图货币总量</li><li>UI 总刷新调度</li></ul><h3 id="_2-2-地图共享层" tabindex="-1">2.2 地图共享层 <a class="header-anchor" href="#_2-2-地图共享层" aria-label="Permalink to “2.2 地图共享层”">​</a></h3><p>负责同一地图中的公共真值与公共流程。</p><p>适合放：</p><ul><li>当前波次</li><li>关卡进度</li><li>地图内公共资源</li><li>已激活机关状态</li><li>地图级广播协调</li></ul><h3 id="_2-3-系统流程层" tabindex="-1">2.3 系统流程层 <a class="header-anchor" href="#_2-3-系统流程层" aria-label="Permalink to “2.3 系统流程层”">​</a></h3><p>负责更高层的流程控制。</p><p>适合放：</p><ul><li>切图</li><li>胜负判定</li><li>全局计时器</li><li>全局音频流程</li><li>跨地图流程状态</li></ul><h3 id="_2-4-ui-显示层" tabindex="-1">2.4 UI 显示层 <a class="header-anchor" href="#_2-4-ui-显示层" aria-label="Permalink to “2.4 UI 显示层”">​</a></h3><p>负责：</p><ul><li>显示血量</li><li>显示货币</li><li>显示背包</li><li>接收按钮点击</li><li>展示弹窗</li></ul><p>关键原则：</p><blockquote><p>UI 更偏显示与输入，不应该变成真值大脑。</p></blockquote><hr><h2 id="_3-一个推荐的最小项目拆法" tabindex="-1">3. 一个推荐的最小项目拆法 <a class="header-anchor" href="#_3-一个推荐的最小项目拆法" aria-label="Permalink to “3. 一个推荐的最小项目拆法”">​</a></h2><h2 id="_3-1-玩家对象" tabindex="-1">3.1 玩家对象 <a class="header-anchor" href="#_3-1-玩家对象" aria-label="Permalink to “3.1 玩家对象”">​</a></h2><p>建议负责：</p><ul><li>输入响应</li><li>自身移动</li><li>自身动作切换</li><li>自身生命状态</li><li>自身攻击触发</li><li>向外发事件</li></ul><p>不建议负责：</p><ul><li>全局商店库存</li><li>地图总任务状态</li><li>所有 UI 的直接刷新</li></ul><h2 id="_3-2-敌人对象" tabindex="-1">3.2 敌人对象 <a class="header-anchor" href="#_3-2-敌人对象" aria-label="Permalink to “3.2 敌人对象”">​</a></h2><p>建议负责：</p><ul><li>自己的 AI 行为</li><li>自己的血量</li><li>命中/死亡反馈</li><li>死亡时发事件</li></ul><h2 id="_3-3-地图控制对象" tabindex="-1">3.3 地图控制对象 <a class="header-anchor" href="#_3-3-地图控制对象" aria-label="Permalink to “3.3 地图控制对象”">​</a></h2><p>建议单独准备一个类似“地图控制器”的对象，用于统一处理：</p><ul><li>地图公共广播</li><li>波次推进</li><li>地图事件开关</li><li>地图级数据源</li></ul><h2 id="_3-4-ui-控制对象-ui-页面" tabindex="-1">3.4 UI 控制对象 / UI 页面 <a class="header-anchor" href="#_3-4-ui-控制对象-ui-页面" aria-label="Permalink to “3.4 UI 控制对象 / UI 页面”">​</a></h2><p>建议负责：</p><ul><li>读数据并显示</li><li>按钮点击后发广播</li><li>只做轻逻辑</li></ul><p>关键原则：</p><blockquote><p>UI 不要直接成为所有系统的真值中心。</p></blockquote><h2 id="_3-5-系统级流程" tabindex="-1">3.5 系统级流程 <a class="header-anchor" href="#_3-5-系统级流程" aria-label="Permalink to “3.5 系统级流程”">​</a></h2><p>适合统一管理：</p><ul><li>游戏结束</li><li>返回大厅</li><li>切换地图</li><li>总倒计时</li></ul><hr><h2 id="_4-真值与显示必须分开" tabindex="-1">4. 真值与显示必须分开 <a class="header-anchor" href="#_4-真值与显示必须分开" aria-label="Permalink to “4. 真值与显示必须分开”">​</a></h2><p>这是项目能不能长期维护的分水岭。</p><h3 id="错误写法" tabindex="-1">错误写法 <a class="header-anchor" href="#错误写法" aria-label="Permalink to “错误写法”">​</a></h3><ul><li>UI 文本上的数字就是货币真值</li><li>血条长度本身就是血量真值</li><li>背包格子当前显示内容就是背包真实数据</li></ul><h3 id="正确写法" tabindex="-1">正确写法 <a class="header-anchor" href="#正确写法" aria-label="Permalink to “正确写法”">​</a></h3><ul><li>货币真值存在地图属性/系统属性/玩家状态里</li><li>UI 只是读取后显示</li><li>背包数据有自己的数据源结构</li><li>格子只是把数据渲染出来</li></ul><p>一句话：</p><blockquote><p><strong>显示层只是脸，真值层才是脑。</strong></p></blockquote><hr><h2 id="_5-广播在项目里怎么用" tabindex="-1">5. 广播在项目里怎么用 <a class="header-anchor" href="#_5-广播在项目里怎么用" aria-label="Permalink to “5. 广播在项目里怎么用”">​</a></h2><p>广播最适合做“通知”，不适合做“藏得过深的复杂黑箱流程”。</p><h3 id="推荐场景" tabindex="-1">推荐场景 <a class="header-anchor" href="#推荐场景" aria-label="Permalink to “推荐场景”">​</a></h3><ul><li>UI 点击“购买” → 广播给地图/系统处理购买</li><li>玩家击杀敌人 → 广播通知任务系统、掉落系统、UI 系统</li><li>关卡条件满足 → 广播通知 UI 弹窗和流程推进</li></ul><h3 id="不推荐场景" tabindex="-1">不推荐场景 <a class="header-anchor" href="#不推荐场景" aria-label="Permalink to “不推荐场景”">​</a></h3><ul><li>所有细碎局部计算都走广播</li><li>广播名完全随手写，没有命名规范</li><li>一个动作要穿过十几层广播才知道发生了什么</li></ul><p>推荐命名思路：</p><ul><li><code>ui.open_bag</code></li><li><code>shop.buy_item</code></li><li><code>battle.enemy_dead</code></li><li><code>task.progress_add</code></li><li><code>map.wave_start</code></li></ul><hr><h2 id="_6-数据放哪-一个简单判断法" tabindex="-1">6. 数据放哪：一个简单判断法 <a class="header-anchor" href="#_6-数据放哪-一个简单判断法" aria-label="Permalink to “6. 数据放哪：一个简单判断法”">​</a></h2><h3 id="放局部变量" tabindex="-1">放局部变量 <a class="header-anchor" href="#放局部变量" aria-label="Permalink to “放局部变量”">​</a></h3><p>如果它只是临时计算中间值。</p><h3 id="放自身属性" tabindex="-1">放自身属性 <a class="header-anchor" href="#放自身属性" aria-label="Permalink to “放自身属性”">​</a></h3><p>如果它属于某个对象自己的状态。</p><p>例如：</p><ul><li>当前血量</li><li>是否在冷却</li><li>当前目标</li></ul><h3 id="放地图属性" tabindex="-1">放地图属性 <a class="header-anchor" href="#放地图属性" aria-label="Permalink to “放地图属性”">​</a></h3><p>如果它是当前地图里多个对象共享的数据。</p><p>例如：</p><ul><li>本局总击杀数</li><li>地图内货币池</li><li>当前波次</li></ul><h3 id="放系统属性" tabindex="-1">放系统属性 <a class="header-anchor" href="#放系统属性" aria-label="Permalink to “放系统属性”">​</a></h3><p>如果它涉及更高层全局流程或跨地图状态。</p><p>例如：</p><ul><li>全局设置</li><li>全局结算流程</li><li>全局统计</li></ul><hr><h2 id="_7-一个小项目也应该遵守的结构纪律" tabindex="-1">7. 一个小项目也应该遵守的结构纪律 <a class="header-anchor" href="#_7-一个小项目也应该遵守的结构纪律" aria-label="Permalink to “7. 一个小项目也应该遵守的结构纪律”">​</a></h2><h3 id="_7-1-不要把所有脚本写在一个对象上" tabindex="-1">7.1 不要把所有脚本写在一个对象上 <a class="header-anchor" href="#_7-1-不要把所有脚本写在一个对象上" aria-label="Permalink to “7.1 不要把所有脚本写在一个对象上”">​</a></h3><p>这会导致：</p><ul><li>找不到入口</li><li>依赖链混乱</li><li>后期难拆</li></ul><h3 id="_7-2-不要让-ui-到处直接改底层状态" tabindex="-1">7.2 不要让 UI 到处直接改底层状态 <a class="header-anchor" href="#_7-2-不要让-ui-到处直接改底层状态" aria-label="Permalink to “7.2 不要让 UI 到处直接改底层状态”">​</a></h3><p>这会导致：</p><ul><li>逻辑分散</li><li>很难排错</li><li>联机同步更难稳</li></ul><h3 id="_7-3-不要一开始就做-大而全" tabindex="-1">7.3 不要一开始就做“大而全” <a class="header-anchor" href="#_7-3-不要一开始就做-大而全" aria-label="Permalink to “7.3 不要一开始就做“大而全””">​</a></h3><p>建议先做最小闭环：</p><ul><li>输入</li><li>状态变化</li><li>反馈显示</li><li>完成一次完整流程</li></ul><h3 id="_7-4-不要让变量命名随意" tabindex="-1">7.4 不要让变量命名随意 <a class="header-anchor" href="#_7-4-不要让变量命名随意" aria-label="Permalink to “7.4 不要让变量命名随意”">​</a></h3><p>尤其是：</p><ul><li>地图属性</li><li>系统属性</li><li>广播名</li><li>结构体字段</li></ul><p>这些必须尽量稳定。</p><hr><h2 id="_8-一个可维护项目的最小闭环示例" tabindex="-1">8. 一个可维护项目的最小闭环示例 <a class="header-anchor" href="#_8-一个可维护项目的最小闭环示例" aria-label="Permalink to “8. 一个可维护项目的最小闭环示例”">​</a></h2><p>以“购买药水”为例：</p><ol><li>UI 点击购买按钮</li><li>UI 发广播 <code>shop.buy_item</code></li><li>地图/系统逻辑收到广播</li><li>判断货币是否足够</li><li>若足够，扣真值货币</li><li>更新背包数据源</li><li>发广播通知 UI 刷新</li><li>UI 重新读取并显示</li></ol><p>这里的关键不是步骤多，而是：</p><ul><li>真值有统一来源</li><li>UI 不直接私自乱改</li><li>各层职责比较清楚</li></ul><hr><h2 id="_9-最适合先模板化的几个系统" tabindex="-1">9. 最适合先模板化的几个系统 <a class="header-anchor" href="#_9-最适合先模板化的几个系统" aria-label="Permalink to “9. 最适合先模板化的几个系统”">​</a></h2><p>建议优先把这些系统做成“结构模板”：</p><ol><li>货币系统</li><li>背包系统</li><li>血量与血条系统</li><li>商店系统</li><li>任务推进系统</li><li>地图波次系统</li></ol><p>因为这些系统最容易在多个项目里反复出现。</p><hr><h2 id="_10-常见失败信号" tabindex="-1">10. 常见失败信号 <a class="header-anchor" href="#_10-常见失败信号" aria-label="Permalink to “10. 常见失败信号”">​</a></h2><p>如果你的项目出现以下情况，通常说明结构开始坏了：</p><ul><li>一个对象里脚本多到自己都找不到</li><li>同一个值在 UI、地图、对象上各存一份</li><li>每加一个功能就要改 5 个地方</li><li>改血量逻辑时背包也出 bug</li><li>广播名字完全无规律</li><li>你只能靠“记忆”维持项目，而不是靠结构</li></ul><hr><h2 id="_11-一句话模板总结" tabindex="-1">11. 一句话模板总结 <a class="header-anchor" href="#_11-一句话模板总结" aria-label="Permalink to “11. 一句话模板总结”">​</a></h2><p>一个更稳的创游世界项目，通常应该遵守这句：</p><blockquote><p><strong>对象负责执行，地图负责共享，系统负责流程，UI负责显示与输入，广播负责解耦，真值与显示必须分离。</strong></p></blockquote><hr><h2 id="_12-自我复盘-这篇文档还要注意什么" tabindex="-1">12. 自我复盘：这篇文档还要注意什么 <a class="header-anchor" href="#_12-自我复盘-这篇文档还要注意什么" aria-label="Permalink to “12. 自我复盘：这篇文档还要注意什么”">​</a></h2><h3 id="_12-1-这篇更偏结构原则-不是平台官方流程图" tabindex="-1">12.1 这篇更偏结构原则，不是平台官方流程图 <a class="header-anchor" href="#_12-1-这篇更偏结构原则-不是平台官方流程图" aria-label="Permalink to “12.1 这篇更偏结构原则，不是平台官方流程图”">​</a></h3><p>它更适合拿来指导项目拆层，而不是当作唯一标准答案。后续如果补到更多官方截图证据，应继续把文中的判断与证据挂钩。</p><h3 id="_12-2-目前仍缺更细案例" tabindex="-1">12.2 目前仍缺更细案例 <a class="header-anchor" href="#_12-2-目前仍缺更细案例" aria-label="Permalink to “12.2 目前仍缺更细案例”">​</a></h3><p>例如：</p><ul><li>任务系统拆层案例</li><li>交互系统拆层案例</li><li>存档兼容案例</li></ul><p>这些适合后续再开子专题承接。</p><hr><h2 id="_13-关联阅读" tabindex="-1">13. 关联阅读 <a class="header-anchor" href="#_13-关联阅读" aria-label="Permalink to “13. 关联阅读”">​</a></h2><ul><li><code>docs/脚本系统/专题研究/创游世界脚本实战架构入门.md</code></li><li><code>docs/脚本系统/专题研究/脚本作用域与数据流深度研究.md</code></li><li><code>docs/教程资料/专题研究/广播机制深度解析.md</code></li><li><code>docs/脚本系统/专题研究/创游世界UI数据同步架构.md</code></li><li><code>docs/脚本系统/专题研究/创游世界背包与货币系统设计入门.md</code></li><li><code>docs/脚本系统/专题研究/创游世界战斗系统设计入门.md</code></li><li><code>docs/脚本系统/专题研究/创游世界广播驱动项目结构实战.md</code></li><li><code>docs/脚本系统/专题研究/创游世界格子UI与列表系统深度解析.md</code></li><li><code>docs/脚本系统/专题研究/创游世界动作状态机入门.md</code></li><li><code>docs/脚本系统/专题研究/创游世界存档与云变量设计入门.md</code></li><li><code>docs/教程资料/专题研究/创游世界学习路线图.md</code></li><li><code>docs/元信息/创游世界术语表.md</code></li></ul>',132)])])}const b=i(d,[["render",h]]);export{_ as __pageData,b as default};
